insert into kb_chunks (content, source, reference, crop, section, lang, embedding) values ('treat infested seed can be effective. Soaking seed in a fungicide solution of 1:1000 for one hour or 1:2000 for five hours has also been shown to be useful. Avoid repeated applications of benomyl since the fungus can develop resistance to this treatment. In cases where resistance to benomyl occurs, use a fungicide that contains triflumizole, propiconazole, prochloraz or a combination of thiram + benomyl.', 'IRRI Rice Knowledge Bank', 'Bakanae (http://www.knowledgebank.irri.org/training/fact-sheets/pest-management/diseases/item/bakanae)', null, 'diseases', 'en', '[0.005115509033203125,0.0257720947265625,0.0677490234375,0.0164794921875,-0.05291748046875,-0.049407958984375,0.046783447265625,0.0172882080078125,0.008880615234375,0.0394287109375,0.0465087890625,-0.0083160400390625,-0.025909423828125,0.003139495849609375,-0.02581787109375,-0.0157928466796875,0.050872802734375,-0.0011186599731445312,-0.07257080078125,-0.0004718303680419922,0.021942138671875,0.026580810546875,-0.0141143798828125,-0.003330230712890625,0.05169677734375,-0.009857177734375,0.0391845703125,0.018890380859375,-0.0029449462890625,-0.040496826171875,0.042510986328125,-0.008514404296875,-0.0264892578125,-0.01531219482421875,-0.0158843994140625,-0.06024169921875,-0.01093292236328125,0.0031757354736328125,-0.045074462890625,-0.01265716552734375,-0.017913818359375,0.03338623046875,-0.0345458984375,-0.015106201171875,-0.0256195068359375,0.029998779296875,-0.0270843505859375,-0.003509521484375,-0.01727294921875,0.0309906005859375,0.0008473396301269531,-0.01474761962890625,-0.019256591796875,0.0176849365234375,-0.0034427642822265625,-0.0075531005859375,-0.00647735595703125,-0.008453369140625,-0.01525115966796875,-0.025909423828125,0.0256195068359375,0.010345458984375,0.03863525390625,-0.0009350776672363281,-0.05169677734375,0.01169586181640625,0.0064239501953125,-0.053497314453125,-0.038970947265625,0.003572463989257